#include <bits/stdc++.h>
using namespace std;

const int N = 2e5 + 5;
int n, m, a[N], ans;

int main() {
    scanf("%d%d", &n, &m);
    for (int i = 1; i <= n; i++) scanf("%d", &a[i]);

    // 从高位往低位贪心：能保住这一位就保住
    for (int b = 29; b >= 0; b--) {
        int x = ans | (1 << b);
        int cnt = 0;
        for (int i = 1; i <= n; i++)
            if ((a[i] & x) == x) cnt++;   // a[i] 包含 x 的所有位
        if (cnt >= m) ans = x;            // 至少 m 个数能一起凑出 x
    }
    printf("%d\n", ans);
    return 0;
}
